package backoff

import "time"

// Delay returns the wait before the given retry attempt, which counts from 1.
// The delay doubles on each attempt (base, 2*base, 4*base, ...) and is capped at max.
func Delay(attempt int, base, max time.Duration) time.Duration {
	if attempt < 1 || base <= 0 || max <= 0 {
		return 0
	}

	d := base
	for i := 1; i < attempt; i++ {
		// Doubling d would exceed max (or overflow), so the cap applies.
		if d > max/2 {
			return max
		}
		d *= 2
	}

	if d > max {
		return max
	}
	return d
}

